[CmdletBinding()]
param([string]$ReceiptPath='ES/Output/WebPageStudio/bootstrap/round-06-deep-design-github.json')
$ErrorActionPreference='Stop';$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path;$p=Join-Path $root $ReceiptPath;if(-not(Test-Path -LiteralPath $p)){throw 'round-progress.missing-receipt'};$j=Get-Content -Raw -Encoding UTF8 $p|ConvertFrom-Json;$findings=@();$trace=@($j.selfReview.trace);foreach($t in $trace){if([string]$t.beforeHash -eq [string]$t.afterHash){$findings+="round-$($t.round):hash-unchanged"};if($null -eq $t.PSObject.Properties['changedSelectors'] -and $null -eq $t.PSObject.Properties['changedFunctions'] -and $null -eq $t.PSObject.Properties['contractDiff']){$findings+="round-$($t.round):substantive-delta-missing"}};[ordered]@{schemaVersion=1;recordType='WebRoundProgressReceipt';status=if($findings.Count){'blocked'}else{'passed'};rounds=$trace.Count;findings=$findings;required=@('changedSelectors','changedFunctions','contractDiff','interactionGate','layoutGate');nonClaims=@('hash change alone is insufficient','does-not-prove real browser clicks')}|ConvertTo-Json -Depth 20
